<?php
require_once '../includes/config.php';
require_permission('manage_site');
$pdo = db();
$title = 'Manage Site';
$defaults = [
 'store_name'=>'ShopNex','hero_eyebrow'=>'NEW SEASON COLLECTION','hero_title'=>'Upgrade Your Lifestyle Today',
 'hero_subtitle'=>'Explore top brands, latest products and amazing deals at ShopNex.',
 'hero_image'=>'https://images.unsplash.com/photo-1607082349566-187342175e2f?auto=format&fit=crop&w=1200&q=85',
 'hero_button'=>'Shop Now','hero_link'=>'products.php','offer_title'=>'Big Electronics Sale',
 'offer_subtitle'=>'Save up to 50% on selected favourites.',
 'offer_image'=>'https://images.unsplash.com/photo-1498049794561-52e0e0c5e3c8?auto=format&fit=crop&w=1200&q=80',
 'offer_button'=>'Explore Deals','offer_link'=>'products.php','theme_primary'=>'#6f2cff','theme_accent'=>'#ff3e8a',
 'footer_tagline'=>'Shop smarter, live better. A modern online shopping center.',
 'support_email'=>'support@shopnex.local','support_phone'=>'+91 98765 43210',
 'theme_style'=>'purple','font_base'=>'Inter, system-ui, sans-serif','font_heading'=>'Inter, system-ui, sans-serif','font_hero'=>'Inter, system-ui, sans-serif','font_products'=>'Inter, system-ui, sans-serif',
 'offer2_title'=>'','offer2_subtitle'=>'','offer2_image'=>'','offer2_button'=>'Shop Now','offer2_link'=>'products.php',
 'offer3_title'=>'','offer3_subtitle'=>'','offer3_image'=>'','offer3_button'=>'Shop Now','offer3_link'=>'products.php',
 'hero_image_position'=>'center center','offer_image_position'=>'center center','offer2_image_position'=>'center center','offer3_image_position'=>'center center'
];
$allowed = array_keys($defaults);
$fontOptions = ['Inter, system-ui, sans-serif'=>'Inter (modern)','Arial, Helvetica, sans-serif'=>'Arial','Georgia, serif'=>'Georgia (serif)','Trebuchet MS, sans-serif'=>'Trebuchet MS','Verdana, sans-serif'=>'Verdana'];
$themes = ['purple'=>'Concept 1 — Modern Purple','blue'=>'Concept 2 — Premium Blue','vibrant'=>'Concept 3 — Vibrant Gradient'];
$positions = ['center center'=>'Center','center top'=>'Top','center bottom'=>'Bottom','left center'=>'Left','right center'=>'Right'];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    check_csrf();
    $values = [];
    foreach ($allowed as $key) {
        if (in_array($key, ['hero_image','offer_image'], true)) continue;
        $value = trim((string)($_POST[$key] ?? $defaults[$key]));
        if (strlen($value) > 2000) $value = substr($value, 0, 2000);
        if ($key === 'theme_style' && !array_key_exists($value, $themes)) { flash('danger','Choose one of the available themes.'); redirect('website.php'); }
        if (str_ends_with($key, '_image_position') && !array_key_exists($value, $positions)) { flash('danger','Choose a valid image position.'); redirect('website.php'); }
        if (in_array($key, ['font_base','font_heading','font_hero','font_products'], true) && !array_key_exists($value, $fontOptions)) { flash('danger','Choose a font from the approved list.'); redirect('website.php'); }
        if (in_array($key, ['theme_primary','theme_accent'], true) && !preg_match('/^#[0-9a-fA-F]{6}$/', $value)) {
            flash('danger', 'Please use valid six-digit hex colors.'); redirect('website.php');
        }
        if (in_array($key, ['hero_link','offer_link'], true) && (str_contains($value, '://') || str_starts_with($value, '//'))) {
            flash('danger', 'Buttons must link to a local store page.'); redirect('website.php');
        }
        $values[$key] = $value;
    }
    foreach (['hero_image','offer_image','offer2_image','offer3_image'] as $imageKey) {
        $existing = site_setting($imageKey, $defaults[$imageKey]);
        $urlKey = $imageKey . '_url';
        $typedUrl = trim((string)($_POST[$urlKey] ?? ''));
        if ($typedUrl !== '') {
            if (!filter_var($typedUrl, FILTER_VALIDATE_URL) || !in_array(strtolower((string)parse_url($typedUrl, PHP_URL_SCHEME)), ['http','https'], true)) {
                flash('danger', 'Image URLs must start with http:// or https://'); redirect('website.php');
            }
            $existing = $typedUrl;
        }
        if (isset($_FILES[$imageKey]) && ($_FILES[$imageKey]['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) {
            $file = $_FILES[$imageKey];
            if ($file['error'] !== UPLOAD_ERR_OK || $file['size'] > 5 * 1024 * 1024) { flash('danger', 'Each image must be under 5 MB.'); redirect('website.php'); }
            $finfo = new finfo(FILEINFO_MIME_TYPE); $mime = $finfo->file($file['tmp_name']);
            $extensions = ['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];
            if (!isset($extensions[$mime])) { flash('danger', 'Upload a JPG, PNG, WEBP, or GIF image.'); redirect('website.php'); }
            $uploadDir = dirname(__DIR__) . '/uploads/site';
            if (!is_dir($uploadDir) && !mkdir($uploadDir, 0755, true)) { flash('danger', 'Could not create the image upload folder.'); redirect('website.php'); }
            $filename = $imageKey . '-' . bin2hex(random_bytes(12)) . '.' . $extensions[$mime];
            if (!move_uploaded_file($file['tmp_name'], $uploadDir . '/' . $filename)) { flash('danger', 'Image upload failed. Check folder permissions.'); redirect('website.php'); }
            $existing = url('uploads/site/' . $filename);
        }
        $values[$imageKey] = $existing;
    }
    foreach ($values as $key => $value) save_site_setting($key, $value);
    flash('success', 'Storefront changes saved. Open the homepage to preview them.'); redirect('website.php');
}
$settings = [];
foreach ($defaults as $key => $default) $settings[$key] = site_setting($key, $default);
require '../includes/header.php';
?>
