<script>
for (const [inputId,previewId] of [['heroUpload','heroPreview'],['offerUpload','offerPreview'],['offer2Upload','offer2Preview'],['offer3Upload','offer3Preview']]) { const input=document.getElementById(inputId), preview=document.getElementById(previewId); input.addEventListener('change',()=>{const file=input.files && input.files[0]; if(!file)return; if(!file.type.startsWith('image/')){input.value='';return;} preview.src=URL.createObjectURL(file);}); }
const heroPosition=document.getElementById('heroPosition'),offerPosition=document.getElementById('offerPosition');if(heroPosition)heroPosition.addEventListener('change',()=>document.getElementById('heroPreview').style.objectPosition=heroPosition.value);if(offerPosition)offerPosition.addEventListener('change',()=>document.getElementById('offerPreview').style.objectPosition=offerPosition.value);if(heroPosition)document.getElementById('heroPreview').style.objectPosition=heroPosition.value;if(offerPosition)document.getElementById('offerPreview').style.objectPosition=offerPosition.value;
function syncColors(){const p=document.getElementById('primaryColor').value,a=document.getElementById('accentColor').value;document.documentElement.style.setProperty('--purple',p);document.documentElement.style.setProperty('--purple2',a);document.getElementById('previewIcon').style.color=p;document.getElementById('previewBadge').style.background=a;document.getElementById('previewButton').style.background=p;document.getElementById('previewButton').style.borderColor=p;}
document.getElementById('primaryColor').addEventListener('input',syncColors);document.getElementById('accentColor').addEventListener('input',syncColors);syncColors();
const bindPreview=(field,target)=>{const el=document.querySelector('[name="'+field+'"]'),out=document.getElementById(target);if(el&&out){el.addEventListener('input',()=>out.textContent=el.value);}};bindPreview('hero_title','heroTextPreview');bindPreview('hero_subtitle','heroSubPreview');bindPreview('hero_button','heroButtonPreview');bindPreview('offer_title','offerTextPreview');bindPreview('offer_subtitle','offerSubPreview');bindPreview('offer_button','offerButtonPreview');for(const n of [2,3]){bindPreview('offer'+n+'_title','offer'+n+'TextPreview');bindPreview('offer'+n+'_subtitle','offer'+n+'SubPreview');bindPreview('offer'+n+'_button','offer'+n+'ButtonPreview');}
const fontSelects=[...document.querySelectorAll('.font-select')];function syncFonts(){const val=k=>document.querySelector('[name="'+k+'"]').value;document.getElementById('fontHeadingPreview').style.fontFamily=val('font_heading');document.getElementById('fontBodyPreview').style.fontFamily=val('font_base');document.getElementById('fontHeadingPreview').style.fontFamily=val('font_hero');document.getElementById('fontPreview').style.fontFamily=val('font_base');}fontSelects.forEach(el=>el.addEventListener('change',syncFonts));syncFonts();
document.getElementById('themeStyle').addEventListener('change',e=>{const themes={purple:['#6f2cff','#ff3e8a'],blue:['#0866c6','#24b8ff'],vibrant:['#4f16db','#ff3d96']};const c=themes[e.target.value];document.getElementById('primaryColor').value=c[0];document.getElementById('accentColor').value=c[1];syncColors();});
</script>
